use std::collections::{HashMap, HashSet};
use std::io::{self, Read};

const DIRS: [&str; 6] = ["n", "s", "e", "w", "u", "d"];

#[derive(Clone, PartialEq)]
enum Loc {
    Room(String),
    Carried,
    In(String),
}

struct Item {
    weight: u64,
    cap: Option<u64>,
    open: bool,
    loc: Loc,
}

#[derive(Clone)]
struct Exit {
    to: String,
    key: Option<String>,
    locked: bool,
}

type Reply = Result<String, String>;

#[derive(Default)]
struct World {
    rooms: HashSet<String>,
    exits: HashMap<(String, usize), Exit>,
    items: HashMap<String, Item>,
    has_player: bool,
    room: String,
    limit: u64,
}

fn num(s: &str) -> Option<u64> {
    if s.is_empty() || s.len() > 6 || !s.bytes().all(|b| b.is_ascii_digit()) {
        return None;
    }
    s.parse().ok()
}

fn dir_index(s: &str) -> Option<usize> {
    DIRS.iter().position(|d| *d == s)
}

impl World {
    fn is_box(&self, name: &str) -> bool {
        self.items.get(name).map_or(false, |it| it.cap.is_some())
    }

    fn is_open(&self, name: &str) -> bool {
        self.items.get(name).map_or(false, |it| it.open)
    }

    fn is_carried(&self, name: &str) -> bool {
        self.items.get(name).map_or(false, |it| it.loc == Loc::Carried)
    }

    fn loc_is_room(&self, name: &str) -> bool {
        self.items
            .get(name)
            .map_or(false, |it| matches!(&it.loc, Loc::Room(r) if *r == self.room))
    }

    fn visible(&self, name: &str) -> bool {
        self.loc_is_room(name) || self.is_carried(name)
    }

    fn set_loc(&mut self, name: &str, loc: Loc) {
        if let Some(it) = self.items.get_mut(name) {
            it.loc = loc;
        }
    }

    fn sorted_where(&self, pred: impl Fn(&Item) -> bool) -> Vec<String> {
        let mut v: Vec<String> = Vec::new();
        for (k, it) in &self.items {
            if pred(it) {
                v.push(k.clone());
            }
        }
        v.sort();
        v
    }

    fn children(&self, name: &str) -> Vec<String> {
        self.sorted_where(|it| matches!(&it.loc, Loc::In(b) if b.as_str() == name))
    }

    fn in_room(&self) -> Vec<String> {
        self.sorted_where(|it| matches!(&it.loc, Loc::Room(r) if *r == self.room))
    }

    fn carried(&self) -> Vec<String> {
        self.sorted_where(|it| it.loc == Loc::Carried)
    }

    fn total(&self, name: &str) -> u64 {
        self.items[name].weight
            + self
                .children(name)
                .iter()
                .map(|c| self.total(c))
                .sum::<u64>()
    }

    fn carried_weight(&self) -> u64 {
        self.carried().iter().map(|n| self.total(n)).sum()
    }

    // True when `x` is `b` itself or an ancestor of `b`.
    fn is_within(&self, b: &str, x: &str) -> bool {
        let mut cur = b.to_string();
        loop {
            if cur == x {
                return true;
            }
            let next = match self.items.get(&cur) {
                Some(it) => it.loc.clone(),
                None => return false,
            };
            match next {
                Loc::In(p) => cur = p,
                _ => return false,
            }
        }
    }

    // True when the item is somewhere inside the carried items, at any depth.
    fn holds(&self, name: &str) -> bool {
        let mut cur = name.to_string();
        loop {
            let loc = match self.items.get(&cur) {
                Some(it) => it.loc.clone(),
                None => return false,
            };
            match loc {
                Loc::Carried => return true,
                Loc::Room(_) => return false,
                Loc::In(p) => cur = p,
            }
        }
    }

    fn resolve_loc(&self, loc: &str) -> Option<Loc> {
        match loc.strip_prefix("in:") {
            Some(b) => {
                if self.is_box(b) {
                    Some(Loc::In(b.to_string()))
                } else {
                    None
                }
            }
            None => {
                if self.rooms.contains(loc) {
                    Some(Loc::Room(loc.to_string()))
                } else {
                    None
                }
            }
        }
    }

    fn declare_item(
        &mut self,
        name: &str,
        weight: &str,
        cap: Option<&str>,
        loc: &str,
        open: bool,
    ) -> bool {
        if self.items.contains_key(name) {
            return false;
        }
        let weight = match num(weight) {
            Some(w) => w,
            None => return false,
        };
        let cap = match cap {
            Some(c) => match num(c) {
                Some(v) => Some(v),
                None => return false,
            },
            None => None,
        };
        let loc = match self.resolve_loc(loc) {
            Some(l) => l,
            None => return false,
        };
        self.items.insert(name.to_string(), Item { weight, cap, open, loc });
        true
    }

    fn add_exit(&mut self, from: &str, dir: &str, to: &str, key: Option<&str>) -> bool {
        let d = match dir_index(dir) {
            Some(d) => d,
            None => return false,
        };
        if !self.rooms.contains(from) || !self.rooms.contains(to) {
            return false;
        }
        let k = (from.to_string(), d);
        if self.exits.contains_key(&k) {
            return false;
        }
        let exit = Exit {
            to: to.to_string(),
            key: key.map(|k| k.to_string()),
            locked: key.is_some(),
        };
        self.exits.insert(k, exit);
        true
    }

    fn add_player(&mut self, room: &str, limit: &str) -> bool {
        if self.has_player || !self.rooms.contains(room) {
            return false;
        }
        let limit = match num(limit) {
            Some(l) => l,
            None => return false,
        };
        self.has_player = true;
        self.room = room.to_string();
        self.limit = limit;
        true
    }

    fn world_line(&mut self, tok: &[&str]) -> bool {
        match tok {
            ["room", name] => self.rooms.insert(name.to_string()),
            ["exit", from, dir, to] => self.add_exit(from, dir, to, None),
            ["exit", from, dir, to, key] => self.add_exit(from, dir, to, Some(*key)),
            ["thing", name, w, loc] => self.declare_item(name, w, None, loc, false),
            ["box", name, w, cap, loc] => self.declare_item(name, w, Some(*cap), loc, false),
            ["box", name, w, cap, loc, "open"] => {
                self.declare_item(name, w, Some(*cap), loc, true)
            }
            ["player", room, limit] => self.add_player(room, limit),
            _ => false,
        }
    }

    fn render(&self, name: &str) -> String {
        let it = &self.items[name];
        if it.cap.is_none() {
            return name.to_string();
        }
        if !it.open {
            return format!("{}{{closed}}", name);
        }
        format!("{}{{{}}}", name, self.render_list(&self.children(name)))
    }

    fn render_list(&self, names: &[String]) -> String {
        names
            .iter()
            .map(|n| self.render(n))
            .collect::<Vec<String>>()
            .join(", ")
    }

    fn look(&self) -> String {
        let mut lines = vec![format!("== {} ==", self.room)];
        let mut exits: Vec<String> = Vec::new();
        for (i, d) in DIRS.iter().enumerate() {
            if let Some(e) = self.exits.get(&(self.room.clone(), i)) {
                if e.locked {
                    exits.push(format!("{}(locked)", d));
                } else {
                    exits.push(d.to_string());
                }
            }
        }
        if exits.is_empty() {
            lines.push("exits: none".to_string());
        } else {
            lines.push(format!("exits: {}", exits.join(" ")));
        }
        let here = self.in_room();
        if here.is_empty() {
            lines.push("items: nothing".to_string());
        } else {
            lines.push(format!("items: {}", self.render_list(&here)));
        }
        lines.join("\n")
    }

    fn inv(&self) -> String {
        let c = self.carried();
        let list = if c.is_empty() {
            "nothing".to_string()
        } else {
            self.render_list(&c)
        };
        format!("carrying: {} ({}/{})", list, self.carried_weight(), self.limit)
    }

    fn go(&mut self, d: usize) -> Reply {
        let (to, locked) = match self.exits.get(&(self.room.clone(), d)) {
            Some(e) => (e.to.clone(), e.locked),
            None => return Err(format!("error: no exit {}", DIRS[d])),
        };
        if locked {
            return Err(format!("error: door {} is locked", DIRS[d]));
        }
        self.room = to.clone();
        Ok(format!("-> {}", to))
    }

    fn take(&mut self, x: &str) -> Reply {
        if !self.loc_is_room(x) {
            return Err(format!("error: no {} here", x));
        }
        let w = self.total(x);
        if self.carried_weight() + w > self.limit {
            return Err("error: too heavy".to_string());
        }
        self.set_loc(x, Loc::Carried);
        Ok(format!("taken {}", x))
    }

    fn take_from(&mut self, x: &str, b: &str) -> Reply {
        if !self.visible(b) {
            return Err(format!("error: no {} here", b));
        }
        if !self.is_box(b) {
            return Err(format!("error: {} is not a box", b));
        }
        if !self.is_open(b) {
            return Err(format!("error: {} is closed", b));
        }
        let inside = self
            .items
            .get(x)
            .map_or(false, |it| it.loc == Loc::In(b.to_string()));
        if !inside {
            return Err(format!("error: {} is not in {}", x, b));
        }
        if self.loc_is_room(b) && self.carried_weight() + self.total(x) > self.limit {
            return Err("error: too heavy".to_string());
        }
        self.set_loc(x, Loc::Carried);
        Ok(format!("taken {} from {}", x, b))
    }

    fn drop_item(&mut self, x: &str) -> Reply {
        if !self.is_carried(x) {
            return Err(format!("error: not carrying {}", x));
        }
        let room = self.room.clone();
        self.set_loc(x, Loc::Room(room));
        Ok(format!("dropped {}", x))
    }

    fn put(&mut self, x: &str, b: &str) -> Reply {
        if !self.visible(x) {
            return Err(format!("error: no {} here", x));
        }
        if !self.visible(b) {
            return Err(format!("error: no {} here", b));
        }
        if !self.is_box(b) {
            return Err(format!("error: {} is not a box", b));
        }
        if self.is_within(b, x) {
            return Err(format!("error: cannot put {} in itself", x));
        }
        if !self.is_open(b) {
            return Err(format!("error: {} is closed", b));
        }
        let inside: u64 = self.children(b).iter().map(|c| self.total(c)).sum();
        let cap = self.items[b].cap.unwrap_or(0);
        let w = self.total(x);
        if inside + w > cap {
            return Err(format!("error: {} is full", b));
        }
        if self.is_carried(b) && self.loc_is_room(x) && self.carried_weight() + w > self.limit {
            return Err("error: too heavy".to_string());
        }
        self.set_loc(x, Loc::In(b.to_string()));
        Ok(format!("put {} in {}", x, b))
    }

    fn set_open(&mut self, b: &str, want: bool) -> Reply {
        if !self.visible(b) {
            return Err(format!("error: no {} here", b));
        }
        if !self.is_box(b) {
            return Err(format!("error: {} is not a box", b));
        }
        if self.is_open(b) == want {
            let state = if want { "open" } else { "closed" };
            return Err(format!("error: {} is already {}", b, state));
        }
        if let Some(it) = self.items.get_mut(b) {
            it.open = want;
        }
        if want {
            Ok(format!("opened {}", b))
        } else {
            Ok(format!("closed {}", b))
        }
    }

    fn unlock(&mut self, d: usize) -> Reply {
        let (locked, key) = match self.exits.get(&(self.room.clone(), d)) {
            Some(e) => (e.locked, e.key.clone()),
            None => return Err(format!("error: no exit {}", DIRS[d])),
        };
        if !locked {
            return Err(format!("error: {} is not locked", DIRS[d]));
        }
        let key = key.unwrap_or_default();
        if !self.holds(&key) {
            return Err(format!("error: need {}", key));
        }
        if let Some(e) = self.exits.get_mut(&(self.room.clone(), d)) {
            e.locked = false;
        }
        Ok(format!("unlocked {}", DIRS[d]))
    }

    fn command(&mut self, tok: &[&str]) -> Reply {
        let bad = || "error: bad command".to_string();
        match tok {
            ["look"] => Ok(self.look()),
            ["inv"] => Ok(self.inv()),
            ["go", d] => match dir_index(d) {
                Some(d) => self.go(d),
                None => Err(bad()),
            },
            ["take", x] => self.take(x),
            ["take", x, "from", b] => self.take_from(x, b),
            ["drop", x] => self.drop_item(x),
            ["put", x, "in", b] => self.put(x, b),
            ["open", b] => self.set_open(b, true),
            ["close", b] => self.set_open(b, false),
            ["unlock", d] => match dir_index(d) {
                Some(d) => self.unlock(d),
                None => Err(bad()),
            },
            _ => Err(bad()),
        }
    }
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let lines: Vec<&str> = input.lines().collect();
    let split = lines
        .iter()
        .position(|l| l.trim() == "---")
        .unwrap_or(lines.len());

    let mut out: Vec<String> = Vec::new();
    let mut world = World::default();
    for (i, line) in lines[..split].iter().enumerate() {
        let tok: Vec<&str> = line.split_whitespace().collect();
        if tok.is_empty() {
            continue;
        }
        if !world.world_line(&tok) {
            out.push(format!("error: bad world line {}", i + 1));
        }
    }

    if !world.has_player {
        out.push("error: no player".to_string());
    } else {
        for line in lines.iter().skip(split + 1) {
            let tok: Vec<&str> = line.split_whitespace().collect();
            if tok.is_empty() {
                continue;
            }
            let reply = match world.command(&tok) {
                Ok(s) | Err(s) => s,
            };
            out.push(reply);
        }
    }

    let failed = out.iter().any(|l| l.starts_with("error:"));
    for l in &out {
        println!("{}", l);
    }
    std::process::exit(if failed { 1 } else { 0 });
}

